// _shared/grocery-category.ts
export function groceryCategory(
  name: string,
):
  | "Овочі та фрукти"
  | "М’ясо та риба"
  | "Молочні продукти"
  | "Бакалія"
  | "Напої"
  | "Побутові товари"
  | "Інше" {
  const text = name.toLocaleLowerCase("uk").replace(/[’'`]/g, "");
  const rules = [
    [
      "Побутові товари",
      /пральн|миюч|мийни|сервет|папір|туалет|губк|мило|шампун|смітт|зубн|рушник|detergent|soap|tissue/,
    ],
    [
      "Напої",
      /(?:вівсян|мигдал|кокос|соєв).{0,12}молок|вода|води|воду|мінерал|сік|соку|соки|кава|кави|чай|чаю|компот|лимонад|вино|вина|пиво|water|juice|coffee|tea\b/,
    ],
    [
      "М’ясо та риба",
      /мяс|курк|куряч|філе|ялович|свинин|індич|фарш|риба|риби|лосос|хек|скумбр|тунец|тунц|кревет|ковбас|бекон|шинка|chicken|beef|pork|salmon|fish|turkey/,
    ],
    [
      "Молочні продукти",
      /молок|сир|сиру|сметан|вершк|йогурт|кефір|ряжан|яйц|яєц|масло|butter|cheese|milk|cream|yogurt|eggs?/,
    ],
    [
      "Овочі та фрукти",
      /картоп|моркв|цибул|помідор|томат|огір|капуст|буряк|буряк|буряку|брокол|кабач|баклаж|перець|перцю|часник|печериц|гриб|зелень|кроп|петруш|салат|рукол|шпинат|авокад|яблук|банан|апельсин|лимон|ягод|груш|виноград|полуниц|potato|onion|carrot|tomato|cucumber|garlic|apple|banana|lettuce|mushroom/,
    ],
    [
      "Бакалія",
      /рис|греч|булгур|пшон|круп|макарон|паст[аиу]|спагеті|борошн|хліб|лаваш|цукор|цукру|сіль|солі|олія|олії|оливков|соняшник|оцет|мед|горіх|квасол|нут|сочевиц|пластів|вівсян|кускус|спеці|паприк|куркум|rice|pasta|flour|bread|sugar|salt|oil|oats/,
    ],
  ] as const;
  return rules.find(([, expression]) => expression.test(text))?.[0] ?? "Інше";
}

// _shared/ingredients.ts
export function parseIngredient(line: string) {
  const fractions: Record<string, string> = {
    "½": "1/2",
    "¼": "1/4",
    "¾": "3/4",
    "⅓": "1/3",
    "⅔": "2/3",
  };
  const normalized = line
    .replace(
      /[½¼¾⅓⅔]/g,
      (c, index, text) =>
        (index > 0 && /\d/.test(text[index - 1]) ? " " : "") + fractions[c],
    )
    .trim();
  const taste = normalized.match(/^(.+?)\s+за\s+смаком\.?$/i);
  if (taste)
    return {
      name: taste[1].trim(),
      quantity: null,
      unit: "за смаком",
      category: groceryCategory(taste[1]),
      price: null,
      note: line,
    };
  if (
    /^\s*\d+(?:[.,]\d+)?\s*(?:ст\.?\s*(?:л\.?|лож(?:ка|ки|ек))|ч\.?\s*(?:л\.?|лож(?:ка|ки|ек)))/i.test(
      normalized,
    )
  )
    return {
      name: line.trim().slice(0, 160),
      quantity: null,
      unit: "за рецептом",
      category: groceryCategory(line),
      price: null,
      note: line,
    };
  const match =
    normalized.match(
      /^(\d+(?:[.,]\d+)?(?:\s+\d+\/\d+)?|\d+\/\d+)\s*(кг|kg|гр?\.?|g|л|l|мл|ml|шт\.?|pcs|cups?|tbsp|tsp|ст\.?\s*л\.?|ч\.?\s*л\.?)?\s+(.+)$/i,
    ) ??
    normalized
      .match(
        /^(.+?)\s*[-—–:]\s*(\d+(?:[.,]\d+)?)\s*(кг|kg|г|g|л|l|мл|ml|шт\.?|pcs)?$/i,
      )
      ?.map((v, i, a) =>
        i === 1 ? a[2] : i === 2 ? a[3] || "" : i === 3 ? a[1] : v,
      );
  if (!match)
    return {
      name: line.trim().slice(0, 160),
      quantity: null,
      unit: "за рецептом",
      category: groceryCategory(line),
      price: null,
      note: line,
    };
  const amount = match[1]
    .replace(",", ".")
    .split(/\s+/)
    .reduce((sum, v) => {
      const parts = v.split("/").map(Number);
      return (
        sum + (parts.length === 2 && parts[1] ? parts[0] / parts[1] : parts[0])
      );
    }, 0);
  const unit =
    (
      {
        kg: "кг",
        g: "г",
        гр: "г",
        "гр.": "г",
        l: "л",
        ml: "мл",
        pcs: "шт.",
        шт: "шт.",
        "шт.": "шт.",
      } as Record<string, string>
    )[(match[2] || "").toLowerCase()] ||
    match[2] ||
    "шт.";
  const supported = ["кг", "г", "л", "мл", "шт."].includes(unit);
  return {
    name: (supported ? match[3] : line)
      .trim()
      .replace(/[;,.]+$/, "")
      .slice(0, 160),
    quantity:
      supported && Number.isFinite(amount) && amount > 0 && amount < 1000000
        ? Math.round(amount * 1000) / 1000
        : null,
    unit: supported ? unit : "за рецептом",
    category: groceryCategory(match[3]),
    price: null,
    note: line,
  };
}

// _shared/urls.ts
export function publicUrl(input: string, base?: string): string {
  try {
    const u = new URL(input, base);
    const h = u.hostname.toLowerCase().replace(/\.$/, "");
    if (
      u.protocol !== "https:" ||
      u.username ||
      u.password ||
      (u.port && u.port !== "443") ||
      h.length > 253 ||
      !h.includes(".") ||
      h.includes(":") ||
      h.startsWith("[") ||
      /^\d+(?:\.\d+)*$/.test(h) ||
      /(?:^|\.)(?:localhost|local|internal|lan|home|test|invalid|onion)$/.test(
        h,
      )
    )
      return "";
    u.hostname = h;
    u.hash = "";
    return u.href.length <= 2048 ? u.href : "";
  } catch {
    return "";
  }
}

